const normalizeText = (value) => String(value ?? "").replace(/\s+/g, " ").trim();
const sourceRecords = new WeakMap();
const attributeRecords = new WeakMap();
const translatedAttrs = ["placeholder", "title", "aria-label", "alt"];

function translateTextNode(node, language) {
  if (!node || !node.parentElement) return;
  if (node.parentElement.closest("[data-preserve-language],.business-name,.team-member-title strong,.team-member-email,.product-card-wa-copy h3,.product-cell-copy strong,.catalog-admin-product strong,.product-code,.business-avatar")) return;
  const current = node.nodeValue;
  if (!current || !current.trim()) return;
  let record = sourceRecords.get(node);
  const source = record && record.translated && current === record.translated ? record.original : current;
  if (language === "en") {
    const replacement = ENGLISH_TEXT[normalizeText(source)];
    if (replacement && replacement !== current) {
      sourceRecords.set(node, { original: source, translated: replacement });
      node.nodeValue = source.replace(/^\s*/, "") === source ? replacement : source.replace(normalizeText(source), replacement);
    } else if (!(record?.translated && current === record.translated)) {
      sourceRecords.set(node, { original: source, translated: null });
    }
  } else if (record?.translated && current === record.translated) {
    node.nodeValue = record.original;
    sourceRecords.set(node, { original: record.original, translated: null });
  }
}

function translateAttribute(element, attribute, language) {
  if (!element?.hasAttribute?.(attribute)) return;
  if (element.closest?.("[data-preserve-language]")) return;
  let byName = attributeRecords.get(element);
  if (!byName) { byName = {}; attributeRecords.set(element, byName); }
  const current = element.getAttribute(attribute) || "";
  const record = byName[attribute];
  const source = record && record.translated && current === record.translated ? record.original : current;
  if (language === "en") {
    const replacement = ENGLISH_TEXT[normalizeText(source)];
    if (replacement && replacement !== current) {
      byName[attribute] = { original: source, translated: replacement };
      element.setAttribute(attribute, replacement);
    } else if (!(record?.translated && current === record.translated)) {
      byName[attribute] = { original: source, translated: null };
    }
  } else if (record?.translated && current === record.translated) {
    element.setAttribute(attribute, record.original);
    byName[attribute] = { original: record.original, translated: null };
  }
}

function walk(node, language) {
  if (!node) return;
  if (node.nodeType === Node.TEXT_NODE) {
    translateTextNode(node, language);
    return;
  }
  if (node.nodeType !== Node.ELEMENT_NODE && node.nodeType !== Node.DOCUMENT_FRAGMENT_NODE) return;
  if (node.nodeType === Node.ELEMENT_NODE) {
    for (const attribute of translatedAttrs) translateAttribute(node, attribute, language);
  }
  const walker = document.createTreeWalker(node, NodeFilter.SHOW_TEXT);
  const textNodes = [];
  while (walker.nextNode()) textNodes.push(walker.currentNode);
  for (const textNode of textNodes) translateTextNode(textNode, language);
  if (node.nodeType === Node.ELEMENT_NODE) {
    for (const child of node.querySelectorAll(translatedAttrs.map((attr) => "[" + attr + "]").join(","))) {
      for (const attribute of translatedAttrs) translateAttribute(child, attribute, language);
    }
  }
}


