export function applyAppLanguage(language) {
  if (typeof document === "undefined") return () => {};
  const lang = language === "en" ? "en" : "es";
  document.documentElement.lang = lang;
  document.title = lang === "en" ? "treseiscinco — Your business, every day" : "treseiscinco — Tu negocio, todos los días";
  const root = document.body;
  walk(root, lang);
  const observer = new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      if (mutation.type === "characterData") translateTextNode(mutation.target, lang);
      else {
        for (const added of mutation.addedNodes || []) walk(added, lang);
        if (mutation.type === "attributes" && mutation.target?.nodeType === 1) {
          translateAttribute(mutation.target, mutation.attributeName, lang);
        }
      }
    }
  });
  observer.observe(root, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: translatedAttrs });
  return () => observer.disconnect();
}
